{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "The highest-transfer analogue, SRT2104, has an absolute oral bioavailability of 13.8% (range 2–27%) in healthy humans after a 0.25 g oral suspension, directly below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Revefenacin, a carbamate-containing drug with high transferability, has absolute oral bioavailability below 3% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Alvimopan has a human oral bioavailability of about 6%, with multiple independent reports confirming low systemic absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Aliskiren, a peptidomimetic renin inhibitor sharing isopropyl, hydroxy, and multiple amide-like features with the query, has an absolute oral bioavailability of 2.6% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Selegiline, a small lipophilic amine, has an absolute oral bioavailability of 4% after a 10 mg oral dose in healthy volunteers, showing that even lipophilic small molecules can be low.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "GHRP-6, a peptide, has systemic availability of about 0.3% in humans after oral administration, indicating very low oral bioavailability for peptide-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Octreotide, a cyclic peptide, has oral bioavailability of 0.3–0.6% in healthy volunteers, supporting low F for peptide-like structures.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence points to low absolute oral bioavailability. The closest analogue (SRT2104, transfer 0.967) has F=13.8%, and every other relevant analogue—including peptide-like, carbamate-containing, and peptidomimetic drugs—has F below 10%, many below 3%. The query's large peptide-like structure with multiple amides, a carbamate, urea, and a hydroxyl is consistent with poor permeability and extensive first-pass metabolism. Therefore the query is predicted to have F < 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the exact query molecule.",
    "Transfer scores are based on analogue relevance, not structural identity; some analogues differ in charge and molecular size.",
    "No explicit permeability or first-pass metabolism data for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

